#include <vector>
using namespace std;

class Solution {
public:
    double champagneTower(int poured, int row, int col) {
        vector<vector<double>> dp(row + 1, vector<double>(row + 1, 0));
        dp[0][0] = poured;

        for (int i = 0; i < row; ++i) {
            for (int j = 0; j <= i; ++j) {
                double overflow = (dp[i][j] - 1) / 2;
                if (overflow > 0) {
                    dp[i + 1][j] += overflow;
                    dp[i + 1][j + 1] += overflow;
                }
            }
        }

        return min(1.0, dp[row][col]);
    }
};
